        {
          "q": "新规背后反映了怎样的城市治理逻辑？",
          "naive": "认为城市管理就是“管住”违规行为。",
          "lens": "新制度主义",
          "lensId": "institutionalism",
          "body": "新制度主义强调，规则不仅是约束，更是<b>社会认知</b>的塑造者。新规的出台，传递了“居住环境优先”的价值导向，但执行中需避免<b>制度刚性</b>带来的“一刀切”，而应通过参与式治理，让居民、商户、社区共同协商，形成被广泛认同的规范。",
          "aha": "规则的真正力量，不在于惩罚，而在于它能否成为人们心中的“理所当然”。"
        }
