          "lensId": "econ_ricardo",
          "body": "李嘉图的<b>地租理论</b>指出，地租是土地边际收益的产物，当租金超过商业经营的剩余价值，企业便无法生存。房东经济追求<b>短期租金最大化</b>，却损害了<b>长期商业生态</b>，这类似于<b>公地悲剧</b>——个体理性导致集体非理性。社会学家鲍曼的“<b>液态现代性</b>”也警示，资本的流动让地方变得不稳定，优质商业如同“液态”般流走。",
