          "body": "从社会学看，巨型IPO是<b>优绩主义</b>的狂欢：它宣称‘赢者通吃’源于能力与创新。但桑德尔提醒我们，优绩的背面是‘优绩的暴政’——当成功被归因于个人奋斗，失败者便被默认为不够努力。这种叙事强化了阶层固化，掩盖了结构性不公。IPO的‘史上最大’标签，恰是优绩神话的缩影。",
