          "body": "<b>工作社会学</b>让我们看见，一条温度线背后是千万户外劳动者的身体与权益。当预报温度与体感温度存在落差，停工避暑的\"红线\"可能迟迟不触发，建筑工、环卫工、快递员便不得不在酷暑中继续裸露作业——数字的差值，落在一个个具体的人身上。",
