          "body": "<b>风险社会理论</b>提醒，现代风险常由制度与技术共同界定。当预警标准落后于真实体感、执行又依赖企业自觉，劳动保护便容易在\"达标\"与\"实际危险\"的缝隙间失灵——高温不是天灾，而是可被制度更好承接的人祸。",
