          "body": "<b>风险社会理论</b>提醒我们，现代社会的危险越来越不是来自自然界本身，而是来自高度互联的系统如何被一次冲击连带放大——台风的路径不确定，会牵动航运、电网、农业、城市排涝一整条链条。当“不确定性”本身成为常态威胁，防灾就从偶发应急变成了日常治理。",
